  'La couverture': g => g.court().A(175, 110, 'At').A(125, 140).A(125, 80).row('b', 3, 290, 60, 290, 190).X(215, 110, 'C').shot(185, 106, 205, 108, 0, 1).lob(210, 120, 135, 150, -30, 2).run(80, 60, 118, 75, 0).run(80, 170, 118, 135, 0)
