  temps: g => g.court().pls('a', [[70, 65], [70, 125], [70, 185], [150, 65], [150, 125], [150, 185]]).pls('b', [[330, 65], [330, 125], [330, 185], [250, 65], [250, 125], [250, 185]]).A(100, 240, 'C', {c: '#16a34a'}).B(300, 240, 'C')
